    }
    
    class AuthRequired(
        
        val `msg`: kotlin.String
        ) : FfiWscdException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class AuthCancelled(
        
        val `msg`: kotlin.String
        ) : FfiWscdException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class ReEnrollmentRequired(
        
        val `msg`: kotlin.String
        ) : FfiWscdException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Plugin(
        
        val `msg`: kotlin.String
        ) : FfiWscdException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Callback(
        
        val `msg`: kotlin.String
        ) : FfiWscdException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Serialization(
        
        val `msg`: kotlin.String
        ) : FfiWscdException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Crypto(
        
        val `msg`: kotlin.String
        ) : FfiWscdException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * A CTAP2 PIN set/use was refused; `reason` says why so the host can
     * re-prompt. `msg` never contains PIN material.
     */
    class Pin(
        
        val `reason`: FfiPinFailure, 
        
        val `msg`: kotlin.String
        ) : FfiWscdException() {
        override val message
            get() = "reason=${ `reason` }, msg=${ `msg` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiWscdException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiWscdException = FfiConverterTypeFfiWscdError.lift(error_buf)
    }

    
}

